// Concatenates supabase/migrations/*.sql (in order) into supabase/setup_all.sql
// for a one-paste setup in the Supabase SQL editor. Run: npm run supabase:bundle
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = 'supabase/migrations';
const files = readdirSync(dir).filter((f) => f.endsWith('.sql')).sort();
const out = [
  '-- GENERATED by `npm run supabase:bundle` – do not edit. Source: supabase/migrations/*.sql',
  '-- Paste into Supabase → SQL Editor → Run (once, on a new project).',
  '',
  ...files.map((f) => `-- ===== ${f} =====\n${readFileSync(join(dir, f), 'utf8').trim()}\n`),
].join('\n');
writeFileSync('supabase/setup_all.sql', out);
console.log(`supabase/setup_all.sql ← ${files.length} migrations`);
